// 設定設備清單
var devices = context.get('devices') || [
   11,12,13,
    14,
   15,16,17,18,19
    ]; // 默認設備清單
// 為每個設備生成一條消息
var msgs = devices.map(deviceID => {
    return {
        deviceID: deviceID // 將設備 ID 添加到消息中
    };
});

// 返回所有消息
return [msgs];

/**
 * P404 查詢指令產生器（不含 CRC）
 * 輸出：msg.payload = Buffer (不含 CRC 的 Modbus 指令)
 *
 * 使用方式：請串接 crc_builder 節點處理 CRC
 */

// 獲取當前設備 ID
var deviceID = msg.deviceID;

// 設定參數
var functionCode = 0x03;           // 功能碼：讀取保持暫存器(Holding Register)
var startAddress = 2090;            // 起始地址
var quantity = 4;                  // 讀取數量

// 將起始地址和數量轉換為兩個字節
var startAddressHigh = (startAddress >> 8) & 0xFF; // 高位
var startAddressLow = startAddress & 0xFF;        // 低位
var quantityHigh = (quantity >> 8) & 0xFF;        // 高位
var quantityLow = quantity & 0xFF;               // 低位

// 組裝指令（不含 CRC）
var message = [
    deviceID,            // 設備地址
    functionCode,        // 功能碼
    startAddressHigh,    // 起始地址高位
    startAddressLow,     // 起始地址低位
    quantityHigh,        // 數量高位
    quantityLow          // 數量低位
];

// 將指令存入 msg.payload
msg.payload = Buffer.from(message);
return msg;

/**
 * MQTT → flow 快取
 * topic: homeassistant/light/single/{id}/{channel}/set/brightness
 * payload: number (0–255)
 */
const topic = String(msg.topic || "");
const parts = topic.split("/");

// 驗證 topic 格式
if (parts.length < 7 || parts[0] !== "homeassistant" || parts[1] !== "light" || parts[2] !== "single" || parts[5] !== "set" || parts[6] !== "brightness") {
    return null; // 格式不符直接忽略
}

const id = parts[3];
const ch = parts[4];
const key = `single_${id}_${ch}_brightness`;

// 驗證 payload
let val = Number(msg.payload);
if (!Number.isFinite(val)) return null;
val = Math.max(0, Math.min(255, Math.round(val)));

// 更新快取
flow.set(key, val);
node.status({ fill: "green", shape: "dot", text: `${key}=${val}` });

return null; // 只更新快取，不往下傳

let t = flow.get("currentTimeout");
if (t) { clearTimeout(t); flow.set("currentTimeout", null); }

global.set("waitingReply", false);
flow.set("currentCmd", null);

return { payload: null }; // 喚醒「發送流程 + timeout」送下一筆

const buf = msg.payload;
if (!Buffer.isBuffer(buf) || buf.length < 4) {  // 依協議調整門檻
    return null; // 略過，讓 timeout 機制處理
}
return msg; // 通過才去解鎖

// 一鍵清除 + 解鎖 + 喚醒（單輸出）
// out[0] → {payload:null} 喚醒「發送流程 + timeout」

// 1) 停掉逾時計時器（避免幽靈回呼）
const t = flow.get("currentTimeout");
if (t) { clearTimeout(t); }

// 2) 清除在途狀態
flow.set("currentTimeout", null);
flow.set("currentCmd", null);
global.set("waitingReply", false);

// 3) 清空佇列
global.set("commandsQueue", []);

// 4) 顯示狀態（方便檢查）
node.status({
  fill: "green",
  shape: "ring",
  text: "已清除, queue=0"
});

// 5) 回傳：直接喚醒發送流程
return { payload: null };

// === 發送流程 + timeout ===
// 功能：
// 1. 從 commandsQueue 取出下一筆指令並發送
// 2. 啟動 Timeout + Retry 機制
// 3. 超過 MAX_RETRY → 丟掉該筆，繼續下一筆
// 4. 部署後自動解鎖（避免 waitingReply 卡死）

const TIMEOUT_MS = 200; // 建議 600~1200ms，依設備回覆時間調整
const MAX_RETRY = 2;   // 最大重送次數；總發送次數 = 1 + MAX_RETRY

// === Queue 狀態 ===
let queue = global.get("commandsQueue");
if (!Array.isArray(queue)) {
  queue = [];
  global.set("commandsQueue", queue);
}

const busy = !!global.get("waitingReply");

// === 若忙碌或佇列空 → 不動作 ===
if (busy || queue.length === 0) return [null, null];

// === 取 FIFO 出列 ===
const cmd = queue.shift();
global.set("commandsQueue", queue);
global.set("waitingReply", true);

// 準備訊息（含 retry 計數）
let outMsg = { payload: cmd, retry: 0 };
flow.set("currentCmd", outMsg);

// === Timeout + Retry 機制 ===
function armTimeout(cur) {
  const timer = setTimeout(() => {
    cur.retry += 1;

    if (cur.retry <= MAX_RETRY) {
      // Retry → 重送同一筆
      flow.set("currentCmd", cur);
      node.send([cur, null]);  // 再送一次到 TCP
      armTimeout(cur);         // 重新掛 Timeout
    } else {
      // 超過 MAX_RETRY → 丟棄這筆，解鎖繼續下一筆
      global.set("waitingReply", false);
      flow.set("currentCmd", null);
      flow.set("currentTimeout", null);

      node.status({
        fill: "red",
        shape: "ring",
        text: "指令超時已丟棄"
      });

      // 觸發下一筆
      node.send([null, { payload: { trigger: true, reason: "timeout" } }]);
    }
  }, TIMEOUT_MS);

  flow.set("currentTimeout", timer);
}

// === 送出第一筆並掛 Timeout ===
armTimeout(outMsg);
return [outMsg, null];

