 * 其中 DATA 的 bit0~bit3 對應通道 1~4
 *
 * 輸出 MQTT：
 *   homeassistant/light/relay/{id}/{channel}/state
 *   payload: "ON" | "OFF"
 *
 * === 如何增加通道數量 ===
 * 1. 修改 for 迴圈上限 (預設 4)
 *      for (let ch = 0; ch < 8; ch++) { ... }   // 8 通道
 * 2. 每增加 8 個通道，會多用到 1 個 data byte
 *      例如 16 通道 → buffer[3], buffer[4] 兩個 byte
 *      例如 24 通道 → buffer[3], buffer[4], buffer[5]
 * 3. 不需改其他程式，因為位元解析邏輯已經處理「跨 byte」情況
 */

// ---- CRC 驗證 ----
function verifyCRC(buf) {
    let crc = 0xFFFF;
    for (let i = 0; i < buf.length - 2; i++) {
        crc ^= buf[i];
        for (let j = 0; j < 8; j++) {
            crc = (crc & 1) ? ((crc >> 1) ^ 0xA001) : (crc >> 1);
        }
    }
    const lo = crc & 0xFF;
    const hi = (crc >> 8) & 0xFF;
    return lo === buf[buf.length - 2] && hi === buf[buf.length - 1];
}

// ---- 主流程 ----
const buf = msg.payload;
if (!Buffer.isBuffer(buf)) return null;
if (buf.length < 5) return null;

const id = buf[0];
const funcCode = buf[1];
const byteCnt = buf[2];

// 檢查功能碼與長度
if (funcCode !== 0x01) return null;
if (buf.length !== 3 + byteCnt + 2) return null;
if (!verifyCRC(buf)) return null;

const mqttMsgs = [];

// === 解析 Relay 狀態 ===
// 預設解析前 4 個 Relay (bit0~bit3)
// ➜ 如果要增加通道數量，修改 for 迴圈上限即可
for (let ch = 0; ch < 4; ch++) {
    // 每 8 個通道使用 1 個 data byte
    const byteIndex = 3 + Math.floor(ch / 8);
    const bitIndex = ch % 8;
    const state = ((buf[byteIndex] >> bitIndex) & 1) ? "ON" : "OFF";

    mqttMsgs.push({
        topic: `homeassistant/light/relay/${id}/${ch + 1}/state`,
        payload: state
    });
}

// ✅ 一次輸出多筆
return [mqttMsgs];

